/**
 * Installable app support is turned off for this project
 * (Website Settings > Installable app).
 *
 * Buildy keeps this file so app code that imports "@/lib/pwa" (for example an
 * install button) still builds. Every call here is a no-op and `canInstall`
 * stays false, so install buttons hide themselves. Buildy restores the full
 * module when the setting is turned back on, so do not edit this file.
 */
import { useEffect, useState } from "react";

type InstallOutcome = "accepted" | "dismissed" | "unavailable";

/** Always false while the installable app is off. */
export function canInstallApp(): boolean {
  return false;
}

/** True when the page is running as an installed app, not in a browser tab. */
export function isInstalledApp(): boolean {
  if (typeof window === "undefined") return false;
  const standalone = (window.navigator as Navigator & { standalone?: boolean }).standalone;
  return window.matchMedia("(display-mode: standalone)").matches || standalone === true;
}

/** No install dialog is available while the installable app is off. */
export async function promptInstallApp(): Promise<InstallOutcome> {
  return "unavailable";
}

/** Install availability never changes while the installable app is off. */
export function onInstallAvailabilityChange(_listener: (canInstall: boolean) => void) {
  return () => {};
}

/** Same shape as the live hook; `canInstall` stays false so install buttons hide. */
export function useInstallPrompt() {
  const [canInstall] = useState(false);
  const [isInstalled] = useState(isInstalledApp);
  return { canInstall, isInstalled, install: promptInstallApp };
}

/** Connectivity helpers do not depend on the installable app, so they stay live. */
export function isOnline(): boolean {
  if (typeof navigator === "undefined") return true;
  return navigator.onLine !== false;
}

export function onOnlineStatusChange(listener: (online: boolean) => void) {
  if (typeof window === "undefined") return () => {};
  const goOnline = () => listener(true);
  const goOffline = () => listener(false);
  window.addEventListener("online", goOnline);
  window.addEventListener("offline", goOffline);
  return () => {
    window.removeEventListener("online", goOnline);
    window.removeEventListener("offline", goOffline);
  };
}

export function useOnlineStatus(): boolean {
  const [online, setOnline] = useState(isOnline);
  useEffect(() => onOnlineStatusChange(setOnline), []);
  return online;
}
